CREATE TABLE accounting_reconciliations (id UUID PRIMARY KEY, company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE, account_id UUID NOT NULL REFERENCES accounting_accounts(id) ON DELETE RESTRICT, statement_date DATE NOT NULL, statement_balance_cents BIGINT NOT NULL, ledger_balance_cents BIGINT NOT NULL, note TEXT NOT NULL DEFAULT '' CHECK(length(note)<=1000), reconciled_by UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,account_id,statement_date));
CREATE INDEX accounting_reconciliations_company_idx ON accounting_reconciliations(company_id,statement_date DESC);
